class Chart extends Canvas {
draw() {
return [
{ op: 'rect', x: 1, y: 2, width: 30, height: 20, radius: 4, fill: '#ff000080', stroke: '#00ff00', strokeWidth: 2 },
{ op: 'rect', x: 0, y: 0, width: 5, height: 5 },
{ op: 'line', x1: 0, y1: 0, x2: 30, y2: 20, width: 2, color: '#0000ff' },
{ op: 'line', x1: 1, y1: 1, x2: 2, y2: 2 },
{ op: 'text', text: 'hi \u2713', x: 3, y: 4, size: 12, color: '#abc', font: 'mono' },
{ op: 'text', text: 'plain' },
{ op: 'icon', name: 'folder', x: 5, y: 6, size: 24, color: '#fff8' },
{ op: 'icon', name: 'user-home' },
{ op: 'pushClip', x: 0, y: 0, width: 10, height: 10, radius: 3 },
{ op: 'pushOpacity', alpha: 0.5 },
{ op: 'rect', x: 0, y: 0, width: 5, height: 5, fill: '#123' },
{ op: 'popOpacity' },
{ op: 'popClip' },
];
}
}
class Bad extends Canvas { draw() { return [{ op: 'rect', x: 0, y: 0, width: 4, height: 4, fill: 'red' }] as any; } }
class Nan extends Canvas { draw() { return [{ op: 'rect', x: NaN, y: 0, width: 4, height: 4 }] as any; } }
const holder = new Box({ width: 300, height: 200 });
holder.add(new Chart({ width: 60, height: 40 }));
const swatch = (x: number, fill: string) => holder.add(new Box({ x, y: 50, width: 8, height: 8, fill }));
swatch(0, '#f00'); swatch(10, '#f008'); swatch(20, '#ff8800'); swatch(30, '#ff880044');
holder.add(new Box({ x: 40, y: 50, width: 20, height: 10, radius: 5, fill: '#112233' }));
holder.add(new Bad({ width: 5, height: 5 }));
holder.add(new Nan({ width: 5, height: 5 }));
globalThis.holder = holder;
